/**
 * Convex Auth hooks for use in Convex mode
 * These hooks provide authentication and profile data from Convex
 *
 * IMPORTANT: These hooks require the Convex generated types.
 * Run `npx convex dev` to generate the types before using these hooks.
 */
import { useAuthActions } from "@convex-dev/auth/react";
import { useConvexAuth, useQuery, useMutation } from "convex/react";

import { API_MODE } from "@/constants/api";

// @ts-ignore - Generated by `npx convex dev`
import { api } from "../../convex/_generated/api";

export interface ConvexUser {
  id: string;
  email?: string;
  name?: string;
  avatar?: string;
  isPremium: boolean;
  isAnonymous: boolean;
}

/**
 * Hook to get auth state and profile data from Convex
 * Only use in Convex mode
 */
export function useConvexAuthState() {
  if (API_MODE !== "convex") {
    throw new Error("useConvexAuthState can only be used in Convex mode");
  }

  const { isLoading, isAuthenticated } = useConvexAuth();
  const profile = useQuery(api.profiles.getCurrentProfile);
  const credits = useQuery(api.credits.getCurrentCredits);

  const user: ConvexUser | null =
    profile && isAuthenticated
      ? {
          id: profile.userId,
          email: profile.email,
          name: profile.fullName,
          avatar: profile.avatarUrl,
          isPremium: profile.isPremium,
          isAnonymous: !profile.email,
        }
      : null;

  return {
    isLoading: isLoading || (isAuthenticated && !profile),
    isAuthenticated,
    user,
    profile,
    credits,
  };
}

/**
 * Hook to get Convex auth actions
 * Only use in Convex mode
 */
export function useConvexAuthActions() {
  if (API_MODE !== "convex") {
    throw new Error("useConvexAuthActions can only be used in Convex mode");
  }

  const { signIn, signOut } = useAuthActions();

  return {
    /**
     * Sign in with email and password
     */
    signInWithEmail: async (email: string, password: string) => {
      try {
        await signIn("password", { email, password, flow: "signIn" });
        return { error: null };
      } catch (error) {
        return { error: error as Error };
      }
    },

    /**
     * Sign up with email, password, and name
     */
    signUpWithEmail: async (email: string, password: string, name: string) => {
      try {
        await signIn("password", { email, password, name, flow: "signUp" });
        return { error: null };
      } catch (error) {
        return { error: error as Error };
      }
    },

    /**
     * Sign in with magic link / OTP
     */
    signInWithMagicLink: async (email: string) => {
      try {
        await signIn("password-otp", { email });
        return { error: null };
      } catch (error) {
        return { error: error as Error };
      }
    },

    /**
     * Sign in anonymously
     */
    signInAnonymously: async () => {
      try {
        await signIn("anonymous");
        return { error: null };
      } catch (error) {
        return { error: error as Error };
      }
    },

    /**
     * Sign out
     */
    signOut: async () => {
      try {
        await signOut();
      } catch (error) {
        console.error("Sign out error:", error);
      }
    },
  };
}

/**
 * Hook to update profile
 * Only use in Convex mode
 */
export function useUpdateProfile() {
  if (API_MODE !== "convex") {
    throw new Error("useUpdateProfile can only be used in Convex mode");
  }

  return useMutation(api.profiles.updateProfile);
}

/**
 * Hook to get user's generation history
 * Only use in Convex mode
 */
export function useGenerations(limit?: number) {
  if (API_MODE !== "convex") {
    throw new Error("useGenerations can only be used in Convex mode");
  }

  return useQuery(api.generations.listUserGenerations, { limit });
}

/**
 * Hook to get user stats
 * Only use in Convex mode
 */
export function useUserStats() {
  if (API_MODE !== "convex") {
    throw new Error("useUserStats can only be used in Convex mode");
  }

  return useQuery(api.generations.getUserStats);
}
